// ⭐⭐ 2026-09-11 ZWEITER KOPF -- HIER WAR DIE URSACHE (Animations-Agent,
// Beleg: Vorher-Screenshot /tmp/schwund_sonder_vorher.png im Bericht):
// Diese Funktion blendete bisher die flachen, UNDURCHSICHTIGEN Vollbild-RGBs
// #gesicht/#gesicht2 (z-index:3) UEBER den echten RGBA-Kopf (#kopf-schicht,
// z-index:2). Diese alten Bilder tragen einen eingebratenen Hintergrund und
// eine andere Kopfposition -- Ergebnis: ein zweiter Kopf mit Rechteckkante.
// Jetzt: dieselben /ausdruck_erweitert/.../frontal/stufe_NN.png-Sequenzen
// (echte 1536x1024-RGBA, laut PIL 10.4% Nicht-Alpha -- identische Silhouette
// wie #kopf-schicht) auf #ausdruck-schicht/#ausdruck-schicht2, die IN
// #kopf-dreh auf derselben Leinwand liegen und denselben Hals-Masken-Verlauf
// tragen. Waehrend der Sequenz wird ausserdem der Mund-Flicken ausgeblendet
// (die Ausdrucks-Frames tragen ihren eigenen Mund) und der
// Erkennungs-Glimmer unterdrueckt (gazeSchritt() prueft _sonderLaeuft) --
// sonst laege ein zweites Augen-/Mundsignal auf dem Ausdrucksgesicht.
let ausdruckAktiv = 1;
let _sonderLaeuft = false;
function sonderausdruckZeigen(register, ausdruck, haltenMs){
  if(_sonderLaeuft) return; // keine zwei Sequenzen gleichzeitig
  haltenMs = haltenMs || 1400;
  _sonderLaeuft = true;
  $("mund-effekt").style.opacity = "0";
  const stufeSrc = n => `/ausdruck_erweitert/${register}/${ausdruck}/frontal/stufe_0${n}.png`;
  const wechsel = (neu, mitSchwung) => {
    const sichtbar = ausdruckAktiv === 1 ? $("ausdruck-schicht") : $("ausdruck-schicht2");
    const versteckt = ausdruckAktiv === 1 ? $("ausdruck-schicht2") : $("ausdruck-schicht");
    if(sichtbar.getAttribute("src") === neu) return;
    versteckt.src = neu;
    // ⭐⭐ PERF-FIX 2026-09-11: gleiche Vor-Synchronisation wie bei
    // kopfRollTick() oben -- atmen() schreibt Transform/Filter nur noch auf
    // die per ausdruckAktiv aktuell sichtbare Ebene, die neu einblendende
    // Ebene braucht den brandaktuellen Wert deshalb hier einmalig.
    versteckt.style.transform = _atmenTransform;
    versteckt.style.filter = _atmenFilter;
    versteckt.style.opacity = "1";
    sichtbar.style.opacity = "0";
    ausdruckAktiv = ausdruckAktiv === 1 ? 2 : 1;
    if(mitSchwung){
      const rahmen = $("gesicht-rahmen");
      rahmen.classList.remove("pose-wechsel");
      requestAnimationFrame(() => rahmen.classList.add("pose-wechsel"));
      setTimeout(() => rahmen.classList.remove("pose-wechsel"), 420);
    }
  };
  const sauber = () => {
    $("ausdruck-schicht").style.opacity = "0";
    $("ausdruck-schicht2").style.opacity = "0";
    $("mund-effekt").style.opacity = "1";
    if(!mundAktivFrames) $("mund-effekt").src = `/mund_keyframes/${MUND_RUHE}.png`;
    _sonderLaeuft = false;
    gesichtNeuZeichnen(true);
  };
  let stufe = 0;
  wechsel(stufeSrc(0), true);
  const hoch = () => {
    stufe++;
    wechsel(stufeSrc(stufe), false);
    if(stufe < 6) setTimeout(hoch, 90);
    else setTimeout(runter, haltenMs);
  };
  const runter = () => {
    stufe--;
    wechsel(stufeSrc(stufe), false);
    if(stufe > 0) setTimeout(runter, 90);
    else setTimeout(sauber, 120); // letzte Stufe (= Neutralbild) kurz halten, dann Ebenen aus
  };
  setTimeout(hoch, 90);
}
window.sonderausdruckZeigen = sonderausdruckZeigen;

// ⭐ 2026-09-11 Auftragsteil E (Animations-Agent): Sonderausdruck aus einem
